@Polynomial.hasseDeriv_mul : ∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f g : Polynomial R),
  (Polynomial.hasseDeriv k) (f * g) =
    ∑ ij ∈ Finset.antidiagonal k, (Polynomial.hasseDeriv ij.1) f * (Polynomial.hasseDeriv ij.2) g

@Polynomial.hasseDeriv_map : ∀ {R : Type u_1} [inst : Semiring R] {S : Type u_2} [inst_1 : Semiring S] (f : R →+* S)
  (k : ℕ) (p : Polynomial R),
  (Polynomial.hasseDeriv k) (Polynomial.map f p) = Polynomial.map f ((Polynomial.hasseDeriv k) p)
